from collections import defaultdict

class Solution:
    def findingUsersActiveMinutes(self, logs: List[List[int]], k: int) -> List[int]:
        active = defaultdict(set)
        for uid, t in logs:
            active[uid].add(t)
        answer = [0] * k
        for minutes in active.values():
            answer[len(minutes) - 1] += 1
        return answer

