import java.util.*;

class Solution {
    public int[] findingUsersActiveMinutes(int[][] logs, int k) {
        Map<Integer, Set<Integer>> active = new HashMap<>();
        for (int[] log : logs) {
            active.computeIfAbsent(log[0], x -> new HashSet<>()).add(log[1]);
        }
        int[] answer = new int[k];
        for (Set<Integer> minutes : active.values()) {
            answer[minutes.size() - 1]++;
        }
        return answer;
    }
}

