class Solution:
    def findingUsersActiveMinutes(self, logs: List[List[int]], k: int) -> List[int]:
        logs.sort()
        answer = [0] * k
        i, n = 0, len(logs)
        while i < n:
            j, uam, prev = i, 0, -1
            while j < n and logs[j][0] == logs[i][0]:
                if logs[j][1] != prev:
                    uam += 1
                    prev = logs[j][1]
                j += 1
            answer[uam - 1] += 1
            i = j
        return answer

