class Solution {
    public int[] findingUsersActiveMinutes(int[][] logs, int k) {
        Arrays.sort(logs, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
        int[] answer = new int[k];
        int i = 0, n = logs.length;
        while (i < n) {
            int j = i, uam = 0, prev = -1;
            while (j < n && logs[j][0] == logs[i][0]) {
                if (logs[j][1] != prev) { uam++; prev = logs[j][1]; }
                j++;
            }
            answer[uam - 1]++;
            i = j;
        }
        return answer;
    }
}

